{
  "name": "jev-compaction-harnesses",
  "version": "0.1.0",
  "description": "fast-jev-compaction for pi and opencode: prune stale tool calls with Jev instead of summarizing your context away.",
  "type": "module",
  "license": "MIT",
  "author": "Ansh Sonkusare",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Ansh-Sonkusare/jev-compaction-harnesses.git"
  },
  "keywords": [
    "pi-package",
    "opencode-plugin",
    "compaction",
    "context",
    "jev",
    "typesafe"
  ],
  "main": "./opencode/plugin.ts",
  "exports": {
    ".": "./opencode/plugin.ts",
    "./opencode": "./opencode/plugin.ts",
    "./pi": "./pi/index.ts"
  },
  "files": [
    "opencode",
    "pi",
    "src",
    "vendor",
    "LICENSE",
    "NOTICE",
    "README.md"
  ],
  "pi": {
    "extensions": [
      "./pi/index.ts"
    ]
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc -p tsconfig.json",
    "sync-upstream": "sh scripts/sync-upstream.sh"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "@earendil-works/pi-tui": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "@earendil-works/pi-tui": {
      "optional": true
    }
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "0.87.1",
    "@opencode-ai/plugin": "1.18.32",
    "@types/bun": "^1.4.2",
    "typescript": "5",
    "@earendil-works/pi-tui": "0.87.1"
  }
}

import { appendFileSync } from "node:fs";
import type { Plugin } from "@opencode-ai/plugin";
import { typesafeApiKey } from "../src/key.ts";
import { JevClient } from "../vendor/fast-jev-compaction/client.ts";
import { compact, reductionRatio } from "../vendor/fast-jev-compaction/compact.ts";
import { collectToolCalls } from "../vendor/fast-jev-compaction/state.ts";
import { applyDecisions, type Decision, decisionsFrom, type OcMessage, toJevMessages } from "./prune.ts";

// Only the plugin may be exported from this module: opencode calls every export as a plugin.

const COMMAND = "jev-compact";

function envNumber(name: string, fallback: number): number {
	const value = Number(process.env[name]);
	return Number.isFinite(value) && value > 0 ? value : fallback;
}

type SessionState = { decisions: Map<string, Decision>; asked: Set<string>; failedAt?: number };
type RunResult = { ran: true; report: string } | { ran: false; report: string };

export const FastJevCompaction: Plugin = async ({ client }) => {
	const triggerTokens = envNumber("FAST_JEV_TRIGGER_TOKENS", 60_000);
	const minNewCalls = envNumber("FAST_JEV_MIN_NEW_CALLS", 8);
	const preserveRecentMessages = envNumber("FAST_JEV_PRESERVE_RECENT", 6);
	const keepThreshold = envNumber("FAST_JEV_KEEP_THRESHOLD", 0.5);
	const retryAfterMs = 5 * 60_000;
	const sessions = new Map<string, SessionState>();

	const logFile = process.env.FAST_JEV_LOG_FILE;
	const log = async (level: "info" | "warn", message: string, extra?: Record<string, unknown>) => {
		if (logFile) {
			try {
				appendFileSync(logFile, `${JSON.stringify({ time: new Date().toISOString(), level, message, ...extra })}\n`);
			} catch (error) {
				console.error(`[fast-jev-compaction] cannot write FAST_JEV_LOG_FILE: ${error instanceof Error ? error.message : String(error)}`);
			}
		}
		try {
			await client.app.log({ body: { service: "fast-jev-compaction", level, message, extra } });
		} catch (error) {
			console.error(`[fast-jev-compaction] ${level}: ${message}`, extra ?? "", `(app.log failed: ${error instanceof Error ? error.message : String(error)})`);
		}
	};

	const toast = (message: string, variant: "info" | "success" | "warning" | "error") =>
		client.tui.showToast({ body: { title: "fast-jev-compaction", message, variant } }).catch(async (error: unknown) => {
			await log("warn", "toast failed", { error: error instanceof Error ? error.message : String(error) });
		});

	const stateFor = (sessionID: string): SessionState => {
		let state = sessions.get(sessionID);
		if (!state) sessions.set(sessionID, (state = { decisions: new Map(), asked: new Set() }));
		return state;
	};

	const runJev = async (sessionID: string, messages: readonly OcMessage[], trigger: "auto" | "command"): Promise<RunResult> => {
		const state = stateFor(sessionID);
		const jev = toJevMessages(applyDecisions(messages, state.decisions));
		const estimatedTokens = Math.ceil(JSON.stringify(jev).length / 4);
		const calls = collectToolCalls(jev, preserveRecentMessages).filter((call) => !call.pinned);
		if (calls.length === 0) {
			return { ran: false, report: `nothing to prune: no finished tool calls outside the newest ${preserveRecentMessages} messages (~${estimatedTokens} tokens in context)` };
		}
		const apiKey = typesafeApiKey();
		if (!apiKey) {
			state.failedAt = Date.now();
			await log("warn", "no TYPESAFE_API_KEY; history left unpruned", { sessionID, trigger });
			return { ran: false, report: "no TYPESAFE_API_KEY found (env or ~/.claude/settings.json); history left unpruned" };
		}
		try {
			const result = await compact(jev, new JevClient({ apiKey }), { preserveRecentMessages, keepThreshold });
			for (const call of calls) state.asked.add(call.tool_use_id);
			for (const [id, decision] of decisionsFrom(jev, result.messages)) state.decisions.set(id, decision);
			state.failedAt = undefined;
			const { stats } = result;
			const reduction = Math.round(reductionRatio(result) * 100);
			await log("info", "pruned tool history", {
				sessionID,
				trigger,
				estimatedTokens,
				reduction,
				calls: stats.calls,
				kept: stats.kept,
				resultsTruncated: stats.resultsDropped,
				callsDropped: stats.callsDropped,
				pinned: stats.pinned,
				requests: stats.requests,
				ms: stats.ms,
			});
			return {
				ran: true,
				report: `Jev reviewed ${calls.length} old tool call(s) in ~${estimatedTokens} tokens of context: dropped ${stats.callsDropped}, truncated ${stats.resultsDropped}, kept ${stats.kept} (${stats.pinned} recent ones untouched). Tool history is ~${reduction}% smaller from the next request on. ${stats.requests} Jev request(s), ${stats.ms} ms.`,
			};
		} catch (error) {
			state.failedAt = Date.now();
			const message = error instanceof Error ? error.message : String(error);
			await log("warn", "Jev failed; history left unpruned", { sessionID, trigger, error: message });
			return { ran: false, report: `Jev failed, history left unpruned: ${message}` };
		}
	};

	return {
		config: async (config) => {
			config.command = config.command ?? {};
			if (!config.command[COMMAND]) {
				config.command[COMMAND] = {
					description: "Prune stale tool calls with Jev now (fast-jev-compaction)",
					template: "fast-jev-compaction: /jev-compact could not run. Reply with one short sentence.",
				};
			}
		},

		"command.execute.before": async (input, output) => {
			if (input.command !== COMMAND) return;
			const response = await client.session.messages({ path: { id: input.sessionID } });
			const messages = (response.data ?? []) as unknown as OcMessage[];
			const { ran, report } = await runJev(input.sessionID, messages, "command");
			await toast(report, ran ? "success" : "warning");
			const text = `fast-jev-compaction report:\n${report}\n\nAcknowledge this report in one short sentence. Do not call any tools.`;
			const first = output.parts.find((part) => part.type === "text");
			if (first && first.type === "text") first.text = text;
		},

		"experimental.chat.messages.transform": async (_input, output) => {
			const messages = output.messages as unknown as OcMessage[];
			const sessionID = messages[0]?.info.sessionID;
			if (!sessionID) return;
			const state = stateFor(sessionID);

			const jev = toJevMessages(applyDecisions(messages, state.decisions));
			const estimatedTokens = Math.ceil(JSON.stringify(jev).length / 4);
			const fresh = collectToolCalls(jev, preserveRecentMessages).filter(
				(call) => !call.pinned && !state.asked.has(call.tool_use_id),
			).length;
			const coolingDown = state.failedAt !== undefined && Date.now() - state.failedAt < retryAfterMs;
			if (estimatedTokens >= triggerTokens && fresh >= minNewCalls && !coolingDown) {
				const { ran, report } = await runJev(sessionID, messages, "auto");
				if (ran) await toast(report, "info");
			}
			messages.splice(0, messages.length, ...applyDecisions(messages, state.decisions));
		},
	};
};

/**
 * fast-jev-compaction for pi (and senpi/omo).
 *
 * pi cannot delete individual history entries: a compaction is a summary
 * string plus the recent tail it keeps (firstKeptEntryId). So the Jev-pruned
 * older messages are rendered verbatim into that summary, and stored in
 * `details.fastJev` so the next compaction can prune them again.
 *
 * Falls back to the host's own summary when the key is missing, Jev fails, the
 * history cannot be fitted, the reduction is below MIN_REDUCTION, or the kept
 * history would take more than MAX_WINDOW_SHARE of the context window.
 *
 * senpi ships a builtin `compaction` extension that summarizes inside its own
 * session_before_compact handler; senpi runs every handler, so it would pay for
 * a summary this handler then replaces. With
 * `"disabledBuiltinExtensions": ["compaction"]` in the agent settings, this
 * extension hosts that builtin itself and calls its handler only on fallback.
 * Plain pi has no such builtin and needs no setting.
 */
import { existsSync, readFileSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { pathToFileURL } from "node:url";
import type {
	CompactionResult,
	ExtensionAPI,
	ExtensionHandler,
	SessionBeforeCompactEvent,
} from "@earendil-works/pi-coding-agent";
import { convertToLlm } from "@earendil-works/pi-coding-agent";
import { Box, Text } from "@earendil-works/pi-tui";
import { typesafeApiKey } from "../src/key.ts";
import { JevClient } from "../vendor/fast-jev-compaction/client.ts";
import { compact, reductionRatio } from "../vendor/fast-jev-compaction/compact.ts";
import { estimateTokens } from "../vendor/fast-jev-compaction/state.ts";
import type { CompactResult, Message } from "../vendor/fast-jev-compaction/types.ts";
import { llmToJev, renderKept } from "./mapping.ts";

const UPSTREAM_COMMIT = "e3f262a7f4d42bd8dd32ced30d26176f7cb545b0";
const MIN_REDUCTION = 0.25;
const MAX_WINDOW_SHARE = 0.25;
const TAG = "fast-jev-compaction";
const BUILTIN_RELATIVE = join("core", "extensions", "builtin", "compaction", "index.js");
const REPORT_ENTRY = "fast-jev-report";

function reportText(stats: CompactResult["stats"]): string {
	const smaller = stats.charsBefore === 0 ? 0 : Math.round(((stats.charsBefore - stats.charsAfter) / stats.charsBefore) * 100);
	return `kept ${stats.messagesAfter}/${stats.messagesBefore} messages verbatim, no summary: ${stats.callsDropped} tool call(s) dropped, ${stats.resultsDropped} output(s) truncated, ${stats.kept} kept. ${smaller}% smaller, ${stats.requests} Jev request(s), ${stats.ms} ms.`;
}

type CompactHandler = ExtensionHandler<
	SessionBeforeCompactEvent,
	{ cancel?: boolean; compaction?: CompactionResult; reason?: string }
>;

interface FastJevDetails {
	version: 1;
	upstreamCommit: string;
	messages: Message[];
	stats: CompactResult["stats"];
}

function builtinCompactionDisabled(): boolean {
	const dirs = [process.env.SENPI_CODING_AGENT_DIR, process.env.PI_CODING_AGENT_DIR, join(homedir(), ".pi", "agent")];
	for (const dir of dirs) {
		if (!dir) continue;
		try {
			const settings = JSON.parse(readFileSync(join(dir, "settings.json"), "utf8"));
			return Array.isArray(settings?.disabledBuiltinExtensions) && settings.disabledBuiltinExtensions.includes("compaction");
		} catch {}
	}
	return false;
}

function findBuiltinCompaction(): string | undefined {
	for (const start of [process.env.SENPI_BIN, process.argv[1]]) {
		if (!start) continue;
		let dir: string;
		try {
			dir = dirname(realpathSync(start));
		} catch {
			continue;
		}
		for (let depth = 0; depth < 5; depth++, dir = dirname(dir)) {
			for (const candidate of [join(dir, BUILTIN_RELATIVE), join(dir, "dist", BUILTIN_RELATIVE)]) {
				if (existsSync(candidate)) return pathToFileURL(candidate).href;
			}
		}
	}
	return undefined;
}

async function loadBuiltin(): Promise<{ factory?: (pi: ExtensionAPI) => void; error?: string } | undefined> {
	if (!builtinCompactionDisabled()) return undefined;
	const url = findBuiltinCompaction();
	if (!url) return { error: "builtin compaction module not found next to the running CLI" };
	try {
		return { factory: (await import(url)).default };
	} catch (error) {
		return { error: error instanceof Error ? error.message : String(error) };
	}
}

const builtin = await loadBuiltin();

function recentGoal(entries: Array<{ type: string; message?: unknown }>, instructions?: string): string {
	const prompts = llmToJev(convertToLlm(entries.filter((e) => e.type === "message").map((e) => e.message) as never) as never)
		.filter((m) => m.role === "user" && m.text.trim() && !m.toolResults?.length)
		.slice(-3)
		.map((m) => m.text.slice(0, 1500));
	return [instructions ? `Compaction focus: ${instructions}` : "", ...prompts].filter(Boolean).join("\n---\n");
}

export default function fastJevCompaction(pi: ExtensionAPI) {
	let builtinCompact: CompactHandler | undefined;
	if (builtin?.factory) {
		const host = new Proxy(pi, {
			get(target, prop, receiver) {
				if (prop === "on") {
					return (event: string, handler: unknown, ...rest: unknown[]) => {
						if (event === "session_before_compact") builtinCompact = handler as CompactHandler;
						else (target.on as (...args: unknown[]) => void)(event, handler, ...rest);
					};
				}
				const value = Reflect.get(target, prop, receiver);
				return typeof value === "function" ? value.bind(target) : value;
			},
		});
		builtin.factory(host);
	} else if (builtin?.error) {
		const message = `${TAG}: could not host the builtin compaction (${builtin.error}); fallbacks use core compaction`;
		pi.on("session_start", async (_event, ctx) => ctx.ui.notify(message, "warning"));
	}

	pi.registerEntryRenderer<{ text: string }>(REPORT_ENTRY, (entry, _options, theme) => {
		const box = new Box(1, 0, (text) => theme.bg("customMessageBg", text));
		box.addChild(new Text(`${theme.fg("accent", "[fast-jev]")} ${entry.data?.text ?? ""}`, 0, 0));
		return box;
	});
	pi.on("session_compact", async (event) => {
		const entry = (event as { compactionEntry?: { details?: unknown } }).compactionEntry;
		const fastJev = (entry?.details as { fastJev?: FastJevDetails } | undefined)?.fastJev;
		if (fastJev) pi.appendEntry<{ text: string }>(REPORT_ENTRY, { text: reportText(fastJev.stats) });
	});

	pi.on("session_before_compact", async (event, ctx) => {
		const { preparation, branchEntries, signal, customInstructions } = event;
		const fallback = (why: string) => {
			if (signal.aborted) return undefined;
			ctx.ui.notify(`${TAG}: fallback to built-in summary (${why})`, "warning");
			return builtinCompact?.(event, ctx);
		};

		const apiKey = typesafeApiKey();
		if (!apiKey) return fallback("no TYPESAFE_API_KEY");

		// Messages kept by our previous compaction stay prunable; anyone else's summary is plain text.
		const previous = [...branchEntries]
			.reverse()
			.find((entry) => entry.type === "compaction") as { details?: { fastJev?: FastJevDetails } } | undefined;
		const carried: Message[] = previous?.details?.fastJev?.messages
			? previous.details.fastJev.messages
			: preparation.previousSummary
				? [{ role: "user", text: `Summary of the earlier conversation:\n${preparation.previousSummary}`, toolUses: [] }]
				: [];
		const messages = [
			...carried,
			...llmToJev(convertToLlm([...preparation.messagesToSummarize, ...preparation.turnPrefixMessages]) as never),
		];
		if (messages.length === 0) return fallback("nothing to compact");

		try {
			const client = new JevClient({
				apiKey,
				fetch: ((url: string, init?: RequestInit) => fetch(url, { ...init, signal })) as typeof fetch,
			});
			const result = await compact(messages, client, {
				// pi already keeps the recent tail verbatim; everything handed to us is a candidate.
				preserveRecentMessages: 0,
				goal: recentGoal(branchEntries as never, customInstructions),
			});
			const ratio = reductionRatio(result);
			if (ratio < MIN_REDUCTION) return fallback(`only ${Math.round(ratio * 100)}% reduction`);

			const summary = renderKept(result.messages, result.stats);
			const summaryTokens = estimateTokens(summary);
			const window = ctx.model?.contextWindow ?? preparation.tokensBefore * 2;
			if (summaryTokens > window * MAX_WINDOW_SHARE) {
				return fallback(`kept history ~${summaryTokens} tokens exceeds ${MAX_WINDOW_SHARE * 100}% of the context window`);
			}

			const { stats } = result;
			ctx.ui.notify(
				`${TAG}: kept ${stats.messagesAfter}/${stats.messagesBefore} messages, no summary (${Math.round(ratio * 100)}% reduction; ${stats.kept} kept, ${stats.resultsDropped} truncated, ${stats.callsDropped} dropped, ${stats.requests} Jev request(s))`,
				"info",
			);
			const details: { fastJev: FastJevDetails } = {
				fastJev: { version: 1, upstreamCommit: UPSTREAM_COMMIT, messages: result.messages, stats },
			};
			return {
				compaction: {
					summary,
					firstKeptEntryId: preparation.firstKeptEntryId,
					tokensBefore: preparation.tokensBefore,
					details,
				},
			};
		} catch (error) {
			if (signal.aborted) return undefined;
			return fallback(error instanceof Error ? error.message : String(error));
		}
	});
}

export * from './types.js';
export * from './request.js';
export * from './client.js';
export * from './state.js';
export * from './compact.js';
export * from './messages.js';
